class Solution:
    def numberOfUniqueGoodSubsequences(self, binary: str) -> int:
        n = len(binary)
        goods = set()
        for mask in range(1, 1 << n):
            s = "".join(binary[i] for i in range(n) if mask >> i & 1)
            if s[0] == "1" or s == "0":
                goods.add(s)
        return len(goods) % (10 ** 9 + 7)

