class Solution {
public:
    int numberOfUniqueGoodSubsequences(string binary) {
        int n = binary.size();
        unordered_set<string> goods;
        for (int mask = 1; mask < (1 << n); ++mask) {
            string s;
            for (int i = 0; i < n; ++i)
                if (mask >> i & 1) s += binary[i];
            if (s[0] == '1' || s == "0") goods.insert(s);
        }
        return (int)(goods.size() % 1000000007LL);
    }
};

