class Solution:
    def numberOfUniqueGoodSubsequences(self, binary: str) -> int:
        MOD = 10 ** 9 + 7
        end1 = end0 = 0
        has_zero = False
        for c in binary:
            if c == "1":
                end1 = (end1 + end0 + 1) % MOD
            else:
                end0 = (end0 + end1) % MOD
                has_zero = True
        return (end0 + end1 + has_zero) % MOD

