class Solution {
public:
    int numberOfUniqueGoodSubsequences(string binary) {
        const int MOD = 1000000007;
        long long end1 = 0, end0 = 0;
        bool hasZero = false;
        for (char c : binary) {
            if (c == '1') {
                end1 = (end1 + end0 + 1) % MOD;
            } else {
                end0 = (end0 + end1) % MOD;
                hasZero = true;
            }
        }
        return (int)((end0 + end1 + (hasZero ? 1 : 0)) % MOD);
    }
};

